import PackageDescription

let package = Package(
    name: "SwiftUI-Shimmer",
    platforms: [
        .macOS(.v10_15),
        .iOS(.v13),
        .watchOS(.v6),
        .tvOS(.v13)
    ],
    products: [
        .library(name: "Shimmer", targets: ["Shimmer"])
    ],
    targets: [
        .target(name: "Shimmer", dependencies: [])
    ]
)

//
